package com.eidolon.sc.mobile;

import org.json.*;import java.io.*;import java.time.*;import java.util.*;

/** Pure rules from original eidolon-sc moments, without image generation or persona copies. */
final class SocialData {
 static final ZoneId TOKYO=ZoneId.of("Asia/Tokyo");static final long DAY=86400000L,HOUR=3600000L;
 static String day(long now){return Instant.ofEpochMilli(now).atZone(TOKYO).toLocalDate().toString();}
 static String budgetDay(String today,String high){LocalDate.parse(today);LocalDate.parse(high);return today.compareTo(high)<0?high:today;}
 static long end(String day){return LocalDate.parse(day).plusDays(1).atStartOfDay(TOKYO).toInstant().toEpochMilli();}
 static String text(JSONObject o,String k,int max,boolean required)throws Exception{Object value=o.opt(k);if(value==null&&!required)return "";if(!(value instanceof String))throw new IOException("字段无效："+k);String s=((String)value).trim();if(s.length()>max||required&&s.isEmpty())throw new IOException("字段无效："+k);return s;}
 static JSONObject object(String raw)throws Exception{if(raw==null||raw.length()>64000)throw new IOException("模型内容过长");int a=raw.indexOf('{'),b=raw.lastIndexOf('}');if(a<0||b<a)throw new IOException("模型没有返回有效结构");return new JSONObject(raw.substring(a,b+1));}
 static JSONObject pair(JSONObject o)throws Exception{return new JSONObject().put("ja",text(o,"ja",2000,true)).put("zh",text(o,"zh",2000,true));}
 static double score(JSONObject personal,String who){return personal.optJSONObject("affinity")==null?50:personal.optJSONObject("affinity").optDouble(who,50);}
 static String tier(double s){return s<20?"cold":s<40?"distant":s<65?"trust":s<85?"close":"intimate";}
 static boolean eligible(JSONObject personal,String who,boolean affinity){JSONObject relations=personal.optJSONObject("relations"),r=relations==null?null:relations.optJSONObject(who);return !affinity||score(personal,who)>=40&&(r==null||!r.optBoolean("cooling"));}
 static double chance(JSONObject personal,String who,boolean affinity){String t=affinity?tier(score(personal,who)):"trust";return t.equals("intimate")?.8:t.equals("close")?.5:t.equals("trust")?.25:0;}
 static long replyAt(long now,JSONObject personal,String who,boolean affinity,Random random){if(!eligible(personal,who,affinity))return 0;String t=affinity?tier(score(personal,who)):"trust";int min=t.equals("intimate")?5:t.equals("close")?15:30,max=t.equals("intimate")?30:t.equals("close")?60:120;return now+(min+random.nextInt(max-min+1))*60000L;}
 static String comment(String value)throws Exception{String s=value==null?"":value.trim();if(s.isEmpty()||s.codePointCount(0,s.length())>140)throw new IOException("评论需要1至140字");return s;}
 static JSONArray strings(JSONObject o,String k,Set<String> known,int max)throws Exception{JSONArray input=o.optJSONArray(k),out=new JSONArray();if(input==null)return out;Set<String> used=new HashSet<>();for(int i=0;i<input.length()&&out.length()<max;i++){String s=input.optString(i);if(known.contains(s)&&used.add(s))out.put(s);}return out;}
 static JSONObject post(String raw,Set<String> circle,Set<String> places)throws Exception{JSONObject input=object(raw),post=pair(input);String place=input.optString("placeId");post.put("placeId",places.contains(place)?place:"");post.put("likes",strings(input,"likes",circle,10));JSONArray comments=input.optJSONArray("comments"),out=new JSONArray();Set<String> authors=new HashSet<>();if(comments!=null)for(int i=0;i<comments.length()&&out.length()<6;i++){JSONObject c=comments.optJSONObject(i);if(c==null||!circle.contains(c.optString("character"))||!authors.add(c.optString("character")))continue;try{out.put(pair(c).put("character",c.getString("character")));}catch(Exception ignored){}}return post.put("comments",out);}
 static JSONObject city(JSONObject input)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"id","name","adm1","adm2","country"})out.put(k,text(input,k,80,k.equals("name")));double lat=input.getDouble("latitude"),lon=input.getDouble("longitude");coordinate(lat,lon);out.put("latitude",lat).put("longitude",lon);String zone=input.optString("zone","");if(!zone.isEmpty())ZoneId.of(zone);return out.put("zone",zone).put("source","qweather_city");}
 static void coordinate(double lat,double lon)throws Exception{if(!Double.isFinite(lat)||!Double.isFinite(lon)||lat< -90||lat>90||lon< -180||lon>180)throw new IOException("经纬度无效");}
 static JSONObject settings(JSONObject input)throws Exception{JSONObject out=new JSONObject().put("enabled",input.optBoolean("enabled",false)).put("perDay",input.optInt("perDay",3)).put("repliesPerDay",input.optInt("repliesPerDay",10)).put("keepDays",input.optInt("keepDays",30)).put("map",input.optString("map","osm")).put("allCharacters",input.optBoolean("allCharacters",!input.has("characters")));if(out.getInt("perDay")<1||out.getInt("perDay")>10||out.getInt("repliesPerDay")<0||out.getInt("repliesPerDay")>30||!Arrays.asList(0,30,90).contains(out.getInt("keepDays"))||!Arrays.asList("osm","google","amap").contains(out.getString("map")))throw new IOException("朋友圈设置无效");JSONArray a=input.optJSONArray("characters");out.put("characters",a==null?new JSONArray():new JSONArray(a.toString()));return out;}
 static boolean selected(JSONObject config,String who){return config.optBoolean("allCharacters")||MediaData.contains(config.optJSONArray("characters"),who);}
 static long drawTime(String day,long now,Random r){List<long[]> windows=new ArrayList<>();LocalDate d=LocalDate.parse(day);for(int[] part:new int[][]{{0,2,1},{7,9,2},{12,13,2},{18,24,4}}){long start=d.atStartOfDay(TOKYO).plusHours(part[0]).toInstant().toEpochMilli(),end=d.atStartOfDay(TOKYO).plusHours(part[1]).toInstant().toEpochMilli();if(end>now+60000)for(int i=0;i<part[2];i++)windows.add(new long[]{Math.max(now+60000,start),end});}if(windows.isEmpty())return 0;long[] w=windows.get(r.nextInt(windows.size()));return w[0]+(long)(r.nextDouble()*Math.max(1,w[1]-w[0]));}
 static String compact(String s,int max){return MediaData.cut(s.replaceAll("[\\r\\n]+"," "),max);}
}
